// Free, exact checks run BEFORE the LLM judge.
const draft = JSON.parse($input.first().json.content[0].text);
const BLOCKLIST = ['guarantee', 'free money', 'act now', 'limited time', 'risk-free'];
const words = draft.body.trim().split(/\s+/).length;
const failures = [];
if (words > 120) failures.push(`body ${words} words (max 120)`);
for (const term of BLOCKLIST) {
  if (draft.body.toLowerCase().includes(term) || draft.subject.toLowerCase().includes(term)) {
    failures.push(`blocked term: ${term}`);
  }
}
return [{ json: { draft, deterministic_pass: failures.length === 0, failures } }];
